"""Apply one frozen CSI300 trend gate to unchanged absorption execution events."""
from __future__ import annotations
import argparse,json
from pathlib import Path
import pandas as pd
from experiments.run_weekly_industry_events import summarize
def run(events_path,benchmark_path,filtered_path,out_json,out_md):
 events=pd.read_csv(events_path);events["signal_date"]=pd.to_datetime(events.signal_date);b=pd.read_csv(benchmark_path);b=b[b.asset=="equity"].copy();b.trade_date=pd.to_datetime(b.trade_date,format="mixed");b=b.sort_values("trade_date");b["sma60"]=b.adj_close.rolling(60,min_periods=60).mean();b["risk_on"]=(b.adj_close>b.sma60)&(b.sma60>b.sma60.shift(20));gate=b.set_index("trade_date").risk_on;events["market_risk_on"]=events.signal_date.map(gate).fillna(False);events["market_gate_status"]=events.market_risk_on.map({True:"ACCEPTED",False:"MARKET_GATE_REJECTED"});events.to_csv(filtered_path,index=False);accepted=events[events.market_risk_on].copy();summary,checks=summarize(accepted);checks["success"]=summary["success_rate"]>=.55;verdict="GO" if all(checks.values()) else ("MARGINAL" if summary["mean_active35"]>0 else "NO-GO");payload={"study":"a-share-absorption-market-regime-v1","data":{"source_events":len(events),"accepted":len(accepted),"acceptance_rate":len(accepted)/len(events) if len(events) else 0},"summary":summary,"decision":{"verdict":verdict,"checks":checks},"events":filtered_path,"limitations":["single precommitted market trend gate","uses existing exploratory execution events","no formal Platform validation authority"]};Path(out_json).write_text(json.dumps(payload,ensure_ascii=False,indent=2)+"\n");Path(out_md).write_text(f"# A股吸收扩散市场环境Gate\n\n- verdict: **{verdict}**\n- accepted: {len(accepted)}/{len(events)}\n- success/outperform/median active35: {summary['success_rate']:.2%}/{summary['outperform_rate']:.2%}/{summary['median_active35']:.2%}\n");return payload
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--events",default="overall/a-share-turnover-absorption-events.csv");p.add_argument("--benchmark",default="overall/a-share-equity-etf-daily-current.csv");p.add_argument("--filtered",default="overall/a-share-absorption-market-gated-events.csv");p.add_argument("--out-json",default="overall/a-share-absorption-market-gate.json");p.add_argument("--out-md",default="overall/a-share-absorption-market-gate.md");a=p.parse_args(argv);payload=run(a.events,a.benchmark,a.filtered,a.out_json,a.out_md);print(json.dumps(payload["summary"],ensure_ascii=False,indent=2));return 0
if __name__=="__main__":raise SystemExit(main())
